let listaNumeros=[];document.addEventListener("DOMContentLoaded",function(){document.getElementById("numero-maximo").addEventListener("input",function(){listaNumeros=[],document.querySelector(".resultado").style.display="none",document.getElementById("numero-sorteado").innerText="",document.getElementById("texto-sorteado").innerText="",console.log("Número máximo alterado. Sorteio reiniciado!")}),document.getElementById("form-sorteador").addEventListener("submit",function(e){e.preventDefault();var t=parseInt(document.getElementById("numero-maximo").value);let o=Math.floor(Math.random()*t)+1;if(listaNumeros.length>=t)document.getElementById("texto-sorteado").innerText="Todos os possíveis números referentes ao número digitado já foram sorteados. O sorteio será reiniciado!",document.getElementById("numero-sorteado").innerText="",document.querySelector(".resultado").style.display="flex",listaNumeros=[];else{for(;listaNumeros.includes(o);)o=Math.floor(Math.random()*t)+1;listaNumeros.push(o),document.getElementById("texto-sorteado").innerText="O número sorteado foi o: ",document.querySelector(".resultado").style.display="flex",document.getElementById("numero-sorteado").innerText=o}console.log("Histórico atual:",listaNumeros)})});